// src/components/VotingPage.js
import React, { useEffect, useState, useMemo } from "react";
import axios from "axios";

const API_URL = "http://localhost:5000";

const THEME = {
  primary: "#B11226",
  primaryDark: "#8E0E1E",
  background: "#F8F9FA",
  white: "#FFFFFF",
  textDark: "#1F2937",
};

function VotingPage({ auth }) {
  const [candidates, setCandidates] = useState([]);
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);

  const [showModal, setShowModal] = useState(false);
  const [modalMessage, setModalMessage] = useState("");
  const [modalType, setModalType] = useState("confirm");
  const [selectedCandidate, setSelectedCandidate] = useState(null);

  useEffect(() => {
    const fetchCandidates = async () => {
      try {
        const res = await axios.get(`${API_URL}/api/candidates`);
        setCandidates(res.data);
      } catch (error) {
        setModalMessage("Failed to load candidates.");
        setModalType("error");
        setShowModal(true);
      } finally {
        setLoading(false);
      }
    };
    fetchCandidates();
  }, []);

  const handleVote = (candidateId) => {
    if (submitting) return;
    setSelectedCandidate(candidateId);
    setModalType("confirm");
    setModalMessage("Are you sure you want to vote? This cannot be changed.");
    setShowModal(true);
  };

  const confirmVote = async () => {
    try {
      setSubmitting(true);

      await axios.post(
        `${API_URL}/api/vote/batch`,
        { candidateIds: [selectedCandidate] },
        {
          headers: {
            Authorization: `Bearer ${auth?.token}`,
          },
        }
      );

      setModalType("success");
      setModalMessage("Your vote has been successfully recorded.");
    } catch (error) {
      setModalType("error");
      setModalMessage("Vote failed or you may have already voted.");
    } finally {
      setSubmitting(false);
    }
  };

  const groupedCandidates = useMemo(() => {
    return candidates.reduce((groups, candidate) => {
      const position = candidate.candidacy;
      if (!groups[position]) groups[position] = [];
      groups[position].push(candidate);
      return groups;
    }, {});
  }, [candidates]);

  if (loading) {
    return (
      <div style={{ padding: 50, textAlign: "center" }}>
        <h2>Loading candidates...</h2>
      </div>
    );
  }

  return (
    <div style={{ backgroundColor: THEME.background, minHeight: "100vh" }}>

      {/* 🔴 HEADER BANNER */}
      <div
        style={{
          backgroundColor: THEME.primary,
          padding: "20px 40px",
          display: "flex",
          alignItems: "center",
          boxShadow: "0 4px 15px rgba(0,0,0,0.2)",
        }}
      >
        <img
          src="/sorsu-logo.png"
          alt="SorSU Logo"
          style={{
            height: 70,
            marginRight: 20,
          }}
        />

        <div style={{ color: "white" }}>
          <h2 style={{ margin: 0, fontWeight: "700" }}>
            SorSU Online Voting System
          </h2>
          <p style={{ margin: 0, opacity: 0.9 }}>
            Official Student Election Portal 2026
          </p>
        </div>
      </div>

      {/* CONTENT */}
      <div
        style={{
          padding: 60,
          maxWidth: 1300,
          margin: "auto",
        }}
      >
        {Object.entries(groupedCandidates).map(([position, list]) => (
          <div key={position} style={{ marginBottom: 60 }}>
            <h2
              style={{
                marginBottom: 30,
                color: THEME.primary,
                borderLeft: `6px solid ${THEME.primary}`,
                paddingLeft: 15,
                fontWeight: "700",
              }}
            >
              {position}
            </h2>

            <div style={{ display: "flex", flexWrap: "wrap", gap: 30 }}>
              {list.map((candidate) => (
                <div
                  key={candidate._id}
                  style={{
                    width: 300,
                    backgroundColor: THEME.white,
                    borderRadius: 15,
                    padding: 25,
                    boxShadow: "0 15px 30px rgba(0,0,0,0.05)",
                    textAlign: "center",
                    borderTop: `5px solid ${THEME.primary}`,
                  }}
                >
                  {candidate.image && (
                    <img
                      src={`${API_URL}/uploads/${candidate.image}`}
                      alt={`${candidate.firstName} ${candidate.lastName}`}
                      style={{
                        width: "100%",
                        height: 220,
                        objectFit: "cover",
                        borderRadius: 10,
                        marginBottom: 15,
                        border: `3px solid ${THEME.primary}`,
                      }}
                    />
                  )}

                  <h3>
                    {candidate.firstName} {candidate.lastName}
                  </h3>

                  <p>
                    {candidate.yearLevel} - {candidate.block}
                  </p>

                  <p>
                    Partylist: {candidate.partylist || "Independent"}
                  </p>

                  <button
                    onClick={() => handleVote(candidate._id)}
                    disabled={submitting}
                    style={{
                      marginTop: 20,
                      padding: "12px",
                      width: "100%",
                      backgroundColor: THEME.primary,
                      color: "#fff",
                      border: "none",
                      borderRadius: 8,
                      fontWeight: "600",
                      cursor: "pointer",
                    }}
                  >
                    Vote
                  </button>
                </div>
              ))}
            </div>
          </div>
        ))}
      </div>

      {/* MODAL stays same as your previous version */}
    </div>
  );
}

export default VotingPage;
